# Auditree activity agent installer __AGENT_VERSION__ -- generated by Odoo (xn_activity).
# Endpoint Central: Computer Configuration > Custom Script, run as SYSTEM:
#   powershell.exe -NoProfile -ExecutionPolicy Bypass -File install.ps1
#   powershell.exe -NoProfile -ExecutionPolicy Bypass -File install.ps1 -Uninstall
# Running it again updates in place. Exit code 0 = success, 1 = failure.
param([switch]$Uninstall)

$ErrorActionPreference = 'Stop'
$AppDir   = Join-Path $env:ProgramData 'XnActivity'
$Agent    = Join-Path $AppDir 'agent.ps1'
$TaskName = 'Auditree Activity Agent'
$AgentB64 = '__AGENT_B64__'

function Stop-Agents {
    Get-CimInstance Win32_Process -Filter "Name='powershell.exe'" -ErrorAction SilentlyContinue |
        Where-Object { $_.CommandLine -like '*XnActivity\agent.ps1*' } |
        ForEach-Object { Invoke-CimMethod -InputObject $_ -MethodName Terminate | Out-Null }
}

try {
    Unregister-ScheduledTask -TaskName $TaskName -Confirm:$false -ErrorAction SilentlyContinue
    Stop-Agents

    if ($Uninstall) {
        if (Test-Path $AppDir) { Remove-Item $AppDir -Recurse -Force }
        Write-Output 'XnActivity: uninstalled'
        exit 0
    }

    if (-not (Test-Path $AppDir)) { New-Item -ItemType Directory -Path $AppDir | Out-Null }
    [IO.File]::WriteAllBytes($Agent, [Convert]::FromBase64String($AgentB64))

    # SYSTEM and Administrators full control; Users read and execute only.
    & icacls.exe $AppDir /inheritance:r /grant:r '*S-1-5-18:(OI)(CI)F' '*S-1-5-32-544:(OI)(CI)F' '*S-1-5-32-545:(OI)(CI)RX' | Out-Null
    if ($LASTEXITCODE -ne 0) { throw "icacls failed with $LASTEXITCODE" }

    $psArgs = "-NoProfile -NonInteractive -ExecutionPolicy Bypass -WindowStyle Hidden -File `"$Agent`""
    if ([Environment]::OSVersion.Version.Build -ge 22000) {
        $action = New-ScheduledTaskAction -Execute 'conhost.exe' -Argument "--headless powershell.exe $psArgs"
    } else {
        $action = New-ScheduledTaskAction -Execute 'powershell.exe' -Argument $psArgs
    }
    $atLogon = New-ScheduledTaskTrigger -AtLogOn
    $every15 = New-ScheduledTaskTrigger -Once -At (Get-Date).Date -RepetitionInterval (New-TimeSpan -Minutes 15)
    $users = (New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-545')).Translate([System.Security.Principal.NTAccount]).Value
    $principal = New-ScheduledTaskPrincipal -GroupId $users -RunLevel Limited
    $settings = New-ScheduledTaskSettingsSet -MultipleInstances Parallel -ExecutionTimeLimit ([TimeSpan]::Zero) `
        -AllowStartIfOnBatteries -DontStopIfGoingOnBatteries -StartWhenAvailable
    Register-ScheduledTask -TaskName $TaskName -Action $action -Trigger @($atLogon, $every15) `
        -Principal $principal -Settings $settings -Description 'Reports active/idle time to Odoo (xn_activity).' | Out-Null

    # Start it now for whoever is signed in; otherwise it starts at next logon.
    try { Start-ScheduledTask -TaskName $TaskName } catch { }

    Write-Output 'XnActivity: installed __AGENT_VERSION__'
    exit 0
} catch {
    Write-Output "XnActivity: failed: $($_.Exception.Message)"
    exit 1
}
